function targetOptionsValid(a){if(a.allyTargets&&a.allyTargets.length===0&&a.requiresAllyTarget)return false;if(a.multiTarget&&(extraTargetIds.length<(a.multiTarget.min??0)||extraTargetIds.length>(a.multiTarget.max??Infinity)))return false;return true;}

function chooseTarget(id,focus=false){if(busy||!selection)return;const s=selectedAction(),ids=s?.targets?.length?s.targets:[battle.currentId];if(!ids.includes(id))return;targetId=id;playAudio('select');renderTargets();if(focus)$('targetList').querySelector('.selected')?.focus({preventScroll:true});}
