function showHistory(){const entries=window.RELEASE_NOTES?.entries||[];$('historyContent').innerHTML=entries.map(e=>`<h3>${esc(e.version)} · ${esc(e.stage)}</h3><p>${esc(e.summary||'本次反馈与改动进展')}</p>${e.requested?'<ol>'+e.requested.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ol>':''}${e.decisions?'<p>'+e.decisions.map(esc).join('；')+'</p>':''}${e.validation?'<p>验证：'+esc(JSON.stringify(e.validation))+'</p>':''}${e.limitations?'<p>未验/限制：'+e.limitations.map(esc).join('；')+'</p>':''}`).join('');modalOpen('historyDialog');}

function showMigration(text){$('migrationNotice').textContent=text;$('migrationNotice').classList.remove('hidden');}
function renderTacticalNotice(){const text=battle.living('enemy').map(e=>({e,intent:enemyDanger(e)})).filter(x=>x.intent).map(x=>'危险 · '+x.e.name+' / '+x.intent.name+'：'+(x.intent.description||x.intent.counterplayText||'')).join(' · ');$('tacticalNotice').textContent=text;$('tacticalNotice').classList.toggle('hidden',!text||!!battle.result||menuOpen||!!selection);}

